// Which narration file (if any) belongs to each scene. Shared by voiceover.mjs, render.mjs, qa.mjs and export.mjs.
// - storyboard.voiceover === false: music-only — no narration is used, even if audio files exist.
// - storyboard.voiceover === true: every scene with `narration` text needs a file generated by voiceover.mjs FOR THAT
//   TEXT (and voice/rate). Missing or stale files are errors, never silently dropped.
// - voiceover unset: hand-made files in audio/<scene>.* are used as-is (bring-your-own narration).
// Generated files that no longer match a narrated scene are ignored.
import fs from 'node:fs';
import path from 'node:path';
import crypto from 'node:crypto';

export const AUDIO_EXTS = ['aiff', 'wav', 'mp3', 'm4a'];
export const MANIFEST = 'voiceover.json';
// Identity of one synthesized line: changing the text, voice or rate makes the old file stale.
export const lineKey = (sb, s) => crypto.createHash('sha256').update(JSON.stringify([s.narration, sb.voice ?? null, sb.voiceRate ?? null, ...(sb.tts ? [sb.tts, sb.voiceSpeed ?? null] : []), sb.voicePolish === false ? 'raw' : 'polish-v1'])).digest('hex');

export function readManifest(flowDir) {
  try { return JSON.parse(fs.readFileSync(path.join(flowDir, 'audio', MANIFEST), 'utf8')); } catch { return null; }
}

export function resolveNarration(flowDir, sb) {
  const files = {};
  const errors = [];
  if (sb.voiceover === false) { for (const s of sb.scenes) files[s.id] = null; return { files, errors }; }
  const generated = readManifest(flowDir)?.scenes ?? {};
  for (const s of sb.scenes) {
    const file = AUDIO_EXTS.map((e) => path.join(flowDir, 'audio', `${s.id}.${e}`)).find((f) => fs.existsSync(f)) ?? null;
    const gen = generated[s.id];
    const isGenerated = gen && file && path.basename(file) === gen.file;
    if (sb.voiceover === true && s.narration) {
      if (!file) errors.push(`scene ${s.id}: narration audio missing — run voiceover.mjs`);
      else if (isGenerated && gen.key !== lineKey(sb, s)) errors.push(`scene ${s.id}: narration audio is stale (script, voice or rate changed) — run voiceover.mjs again`);
      files[s.id] = file;
    } else {
      // A generated file whose scene is no longer narrated is stale; hand-made files are kept.
      files[s.id] = isGenerated && (!s.narration || gen.key !== lineKey(sb, s)) ? null : file;
    }
  }
  return { files, errors };
}
